            sections = listOf(
                TheorySection(TheorySectionType.RULE, "Что такое HAY",
                    body = "**HAY** [ай] — это **безличная форма** глагола **HABER**, которая означает **«есть / имеется / существует»**.\n\n**Главные особенности:**\n1. **Не меняется по числу.** Одинаково для ед. и мн.:\n   • Hay **un** libro. (Есть одна книга.)\n   • Hay **diez** libros. (Есть 10 книг.)\n   • Hay libros. (Есть книги.)\n\n2. **Не имеет подлежащего.** Это **безличное** выражение, как русское «есть» в смысле существования.\n\n3. **После hay используется НЕопределённый артикль** (un, una, unos, unas) или **никакого** артикля:\n   • ✅ Hay un perro. (Есть собака.)\n   • ✅ Hay perros. (Есть собаки.)\n   • ❌ ~~Hay el perro~~ (с el — неверно)\n\n4. **Используется для существования** — «что-то существует в мире / в этом месте».\n\n**Только одна форма** — hay. В прошлом будет **había** (был/были), в будущем **habrá** (будет). Но в Presente — только **hay**."),
