                TheorySection(TheorySectionType.MNEMONIC, "🧠 Запомнить через 3 вопроса",
                    body = "**Чтобы выбрать hay или está, задай 3 вопроса:**\n\n**Вопрос 1: Известное или новое?**\n• Новое (впервые упоминаешь) → **hay**\n• Известное (уже говорил) → **está/están**\n\n**Вопрос 2: Артикль перед сущ.?**\n• un/una/unos/unas или ничего → **hay**\n• el/la/los/las → **está/están**\n• Имя собственное → **está/están**\n\n**Вопрос 3: Что хочу сказать?**\n• «Существует / есть в этом месте» → **hay**\n• «Где находится / расположен» → **está/están**\n\n**Пример теста:**\n• «Есть кафе?» → Новое + un → **¿Hay un café?**\n• «Где кафе?» → Известное + el → **¿Dónde está el café?**\n• «На столе книги.» → Что есть → **Hay libros sobre la mesa.**\n• «Книги на столе.» → Где они → **Los libros están sobre la mesa.**"),
                TheorySection(TheorySectionType.TIP, "💡 Hay в других временах + полезные обороты",
                    body = "**Hay меняется по временам** (но не по числу!):\n• **Presente:** hay — есть\n• **Imperfecto:** había — было/были\n• **Indefinido:** hubo — было/были (более точечно)\n• **Futuro:** habrá — будет/будут\n• **Condicional:** habría — было бы\n\n**Полезные обороты с hay:**\n• **hay que + inf** = нужно / надо (безличное долженствование)\n  ✅ **Hay que estudiar.** (Нужно учиться.)\n  ✅ **Hay que ir al médico.** (Надо к врачу.)\n• **No hay de qué** = не за что (ответ на спасибо)\n• **No hay problema** = нет проблем\n• **No hay nadie** = никого нет\n• **No hay nada** = ничего нет\n• **Hay que ver** = надо видеть (выражение удивления)\n\n**Madrid фраза:**\n• «¿Qué hay?» (Что слышно? Как дела?) — неформальное приветствие."),
            ),
            keyTakeaways = listOf(
