                TheorySection(TheorySectionType.RULE, "Что такое отклонение e→i",
                    body = "В испанском есть **3 типа отклонения гласной в основе** глагола в Presente:\n1. **e → ie** (querer → quiero, pensar → pienso) — самый частый\n2. **o → ue** (poder → puedo, dormir → duermo) — второй по частоте\n3. **e → i** (pedir → pido, servir → sirvo) — **ТОЛЬКО для -IR глаголов**\n\nЭтот урок — про **третий тип e → i**.\n\n**Правило:** в ударных формах **e** в основе меняется на **i**.\n• pedir → **p**i**do, **p**i**des, **p**i**de, pedimos, pedís, **p**i**den\n• Видишь, как **i** появляется в 4 формах (yo, tú, él, ellos) — это «башмак-отклонение».\n• В nosotros/vosotros **e сохраняется** (pedimos, pedís) — туда ударение падает на окончание.\n\n**Очень важно:** **e → i** работает **ТОЛЬКО для -IR** глаголов. Никогда для -AR или -ER!\n• querer (-ER) → quiero (e → ie, не e → i)\n• pensar (-AR) → pienso (e → ie)\n• pedir (-IR) → pido (e → i) — наш случай"),
