                    body = "**❌ Ошибка 1: применять e→i к -AR или -ER глаголам**\n❌ ~~yo quiro~~ (вместо quiero) — querer это -ER, отклонение e→ie, не e→i.\n❌ ~~yo pinso~~ (вместо pienso) — pensar это -AR, e→ie тоже.\n✅ **Только -IR глаголы получают e→i.**\n\n**❌ Ошибка 2: применять e→i в nosotros/vosotros**\n❌ ~~pidimos~~, ~~sirvimos~~ — НЕТ!\n✅ **pedimos, servimos** — без отклонения (e сохраняется).\n\n**❌ Ошибка 3: путать pedir и preguntar**\n• **pedir** = просить (что-то, тарелку, помощь)\n  ✅ Pido un café. (Прошу/заказываю кофе.)\n• **preguntar** = спрашивать (задать вопрос)\n  ✅ Pregunto al camarero. (Спрашиваю официанта.)\n\n**❌ Ошибка 4: seguir и его особенности написания**\n• yo **sigo** (без \"u\" — c+o)\n• tú **sigues** (с \"u\" — gue для звука [гэ])\n• Правило написания: «g+e/i» = [хэ], а «g+u+e/i» = [гэ].\n\n**❌ Ошибка 5: decir (нерегулярный e→i + yo digo)**\n• **decir** работает как e→i: di**ces**, di**ce**, di**cen**\n• НО в yo форме — нерегулярная: **digo** (не «dico»!).\n• Это «двойная нерегулярность»: и e→i, и -go в yo.\n\n**❌ Ошибка 6: использовать pedir для покупки**\n• **pedir** = просить (бесплатно, например, помощь)\n• **comprar** = покупать\n• **encargar** = заказывать (доставку)\n\n✅ Pido un favor. (Прошу одолжение.)\n✅ Compro pan. (Покупаю хлеб.)\n✅ Encargo una pizza. (Заказываю пиццу с доставкой.)\n\n⚠ Но в ресторане **pedir** = заказывать с меню (просить блюдо):\n✅ Pido una paella. (Заказываю паэлью.)",
