                TheorySection(TheorySectionType.MNEMONIC, "🧠 Как запомнить «башмак e→i»",
                    body = "**Правило «башмака» (boot/zapato)** одинаковое для всех отклоняющихся глаголов:\n\n```\n    yo ●         nos ○\n    tú ●         vos ○\n    él ●         ellos ●\n```\n\n● = отклонение работает (e→i)\n○ = отклонение НЕ работает (сохраняется e)\n\nЭти 4 формы образуют **башмак** — отсюда название.\n\n**Только -IR глаголы делают e→i:**\nЗапомни 5 главных: **PE**dir, **SE**rvir, **RE**petir, **SE**guir, **DE**cir.\n\nПервая буква каждого = **PSRSD** — попробуй прочитать: «PE-Се-Pе-Се-Де». Это твой A1 список e→i глаголов.\n\n**Бонус:** elegir, conseguir, sentir, herir — также e→i. Но базово 5 хватит."),
