            emoji = "🚂", cefr = "A1", readMinutes = 4,
            sections = listOf(
                TheorySection(TheorySectionType.RULE, "Что такое глагол на -AR",
                    body = "В испанском у каждого глагола есть **6 форм** — по одной для каждого лица:\n• yo (я)\n• tú (ты)\n• él / ella / usted (он / она / Вы вежливо)\n• nosotros (мы)\n• vosotros (вы — только Испания)\n• ellos / ellas / ustedes (они / вы Лат.Ам.)\n\nЕсли инфинитив (начальная форма) кончается на **-AR** — это «первая группа». Самая большая и простая.\n\nКак спрягать: **отрезаем -ar** и добавляем окончания. Например, hablar (говорить) → habl- + окончание."),
                TheorySection(TheorySectionType.TABLE, "Окончания -AR",
                    table = TheoryTable(
                        headers = listOf("Лицо", "Окончание", "hablar"),
                        rows = listOf(
                            listOf("yo", "-o", "hablo"),
                            listOf("tú", "-as", "hablas"),
                            listOf("él/ella/usted", "-a", "habla"),
                            listOf("nosotros", "-amos", "hablamos"),
                            listOf("vosotros", "-áis", "habláis"),
                            listOf("ellos/ustedes", "-an", "hablan"),
                        ),
                        highlightedColumns = listOf(1, 2),
                    )),
                TheorySection(TheorySectionType.MNEMONIC, "🚂 Аналогия: поезд с 6 вагонами",
                    body = "Представь глагол как **поезд**. Локомотив — это **корень** (habl-). К нему цепляются **6 вагонов** — по одному для каждого лица.\n\nКаждый вагон имеет свой **номер на боку** — окончание: -o, -as, -a, -amos, -áis, -an.\n\nТы НЕ говоришь «Yo» каждый раз — **окончание уже говорит**, кто действует:\n• habl**o** = уже понятно «я говорю»\n• habl**as** = уже понятно «ты говоришь»\n\nПоэтому испанцы **часто опускают** местоимение."),
                TheorySection(TheorySectionType.EXAMPLES, "5 примеров с контекстом",
                    examples = listOf(
                        TheoryExample("Yo hablo español todos los días.", "Я говорю по-испански каждый день.", "обычное действие"),
                        TheoryExample("¿Tú trabajas en un banco?", "Ты работаешь в банке?", "вопрос — порядок тот же"),
