                TheorySection(TheorySectionType.RULE, "Хитрое слияние: a + el = al",
                    body = "Когда после **«a»** стоит мужской артикль **«el»**, они **сливаются в одно слово**: **al**.\n\n• a + **el** cine = **al** cine (в кино)\n• a + **el** parque = **al** parque (в парк)\n• a + **el** banco = **al** banco (в банк)\n\nДругие артикли НЕ сливаются:\n• a **la** tienda (ж.р. — без слияния)\n• a **los** amigos (мн.ч. — без слияния)\n\nЭто **обязательно**, не вариант стиля. ~~a el cine~~ — ошибка."),
                TheorySection(TheorySectionType.MNEMONIC, "🔀 Аналогия: «a + el» как магнит",
                    body = "Представь **«a»** и **«el»** как два **магнита**. Они стоят рядом — и **щёлк!** — слиплись в **«al»**.\n\nЖенский **«la»** и множественный **«los»** — НЕ магнитятся. Стоят отдельно: **a la** tienda, **a los** amigos.\n\nЭто как русское «во» вместо «в о-» (во дворе, а не в дворе). Просто звучит лучше."),
                TheorySection(TheorySectionType.EXAMPLES, "Куда идём — примеры",
