                    body = "**Condicional = глагол в примерочной**. Стоит перед зеркалом, **примеряет** ситуацию: «А что **БЫ** я сделал, если бы…»\n\nТри образа:\n1. **Гипотеза** — примеряет невозможное: «**comería** la luna» (съел бы луну).\n2. **Вежливость** — примеряет дипломатический костюм: «¿**podrías**...?» (мягче чем «¿puedes?»).\n3. **Мечта** — примеряет красивую жизнь: «**viviría** en París».\n\nОбразование **гениально простое**: берёшь **инфинитив целиком** (НЕ отрезаешь -ar/-er/-ir) и приклеиваешь **-ía/-ías/-ía/-íamos/-íais/-ían**.\n\n• hablar + ía = hablar**ía**\n• comer + ía = comer**ía**\n• vivir + ía = vivir**ía**\n\n**Все 3 группы — одинаково!**"),
