                    body = "**Условное наклонение в просьбах = словесный поклон**.\n\n¿Puedes? = «Ты можешь?» (вопрос с прямым плечом)\n¿Podrías? = «Не мог бы ты?» (лёгкий поклон головой)\n¿Te importaría? = «Тебя не затруднит?» (поклон с шляпой в руке)\n\nЧем **глубже поклон** — тем больше Condicional + всякие формулы.\n\nКлючевые формулы вежливости:\n1. **¿Podrías + инфинитив?** — самая частая\n2. **¿Te importaría + инфинитив?** — буквально «тебе бы не было важно/неприятно?»\n3. **Me gustaría + инфинитив** — «мне бы хотелось»\n4. **Quisiera + инфинитив** — «я хотел бы» (Imp.Subj. — ещё мягче чем Cond)\n5. **¿Serías tan amable de + инфинитив?** — для формальных писем"),
                TheorySection(TheorySectionType.EXAMPLES, "В разных ситуациях",
