                    body = "Когда говоришь «**Я хотел бы**, чтобы...» — нужна **особая конструкция**:\n\n**Главное предложение** в Condicional + **«que»** + **Imperfecto Subjuntivo**\n\n• Me **gustaría** que **vinieras**. (Хотел бы, чтобы ты пришёл.)\n• **Querría** que me **escucharas**. (Хотел бы, чтобы ты меня выслушал.)\n• **Sería** mejor que **estudiaras** más. (Было бы лучше, если бы ты учился больше.)\n\nЭто **обязательное согласование**: главный глагол «бы» — придаточный в Imp.Subj."),
                TheorySection(TheorySectionType.MNEMONIC, "💑 Аналогия: пара танцоров",
                    body = "**Cond + Imp.Subj — танго**. Главный глагол ведёт, придаточный следует.\n\n• Me gustaría **que vinieras** = «Я веду шаг (бы хотел) → ты следуешь (бы пришёл)»\n• Sería mejor **que durmieras** = «Я веду (было бы лучше) → ты следуешь (если бы ты спал)»\n\nЛогика: если **главное предложение гипотетическое** («бы хотел») — то и **придаточное гипотетическое** («бы пришёл»).\n\nЭто **не строгое правило грамматики ради грамматики** — это **математика смысла**. «Хочу» (есть желание) → vengas (Presente Subj). «Хотел бы» (нет желания) → vinieras (Imp.Subj.)."),
