                TheorySection(TheorySectionType.WARNING, "⚠ Не делай так",
                    body = "**1. ~~Me gustaría que vienes~~** — Indicativo после Cond.Que = неправильно. Нужен **Imp.Subj.**: viniera**s**.\n\n**2. ~~Me gusta que vinieras~~** — наоборот: Presente Indic + Imp.Subj = неправильно. Согласуй:\n• Me **gusta** que **vengas** (Pres + Pres.Subj) ✓\n• Me **gustaría** que **vinieras** (Cond + Imp.Subj) ✓\n\n**3. Imp.Subj. имеет 2 формы — обе ОК**: vinieras / viniese (форма -se реже в Латинской Америке, но обе правильны).\n\n**4. Один субъект → инфинитив, нет «que»**:\n• Yo querría **comer**. (Я хотел бы поесть — один субъект, я)\n• Querría que tú **comieras**. (Я хотел бы, чтобы ты поел — два субъекта)\n\nЕсли субъект **один** — НЕ нужен que + Subj!"),
