                TheorySection(TheorySectionType.RULE, "Что такое Ojalá",
                    body = "**Ojalá** — арабское слово (от «иншалла» — «если будет угодно Богу»). Означает «**вот бы / хотелось бы / если бы только**».\n\nПо смыслу = **загадывание желания**.\n\n**3 уровня нереальности** (выбирай форму Subjuntivo по нереальности):\n\n1. **Ojalá + Presente Subjuntivo** = желание возможное (есть шанс):\n   - **Ojalá venga** Juan. (Вот бы Хуан пришёл — может прийти.)\n\n2. **Ojalá + Imperfecto Subjuntivo** = желание сейчас, но невозможное:\n   - **Ojalá supiera** la respuesta. (Знать бы ответ — но не знаю.)\n\n3. **Ojalá + Pluscuamperfecto Subj** = желание о прошлом (упустил):\n   - **Ojalá hubiera estudiado**. (Вот бы я учился — но не учился.)"),
                TheorySection(TheorySectionType.MNEMONIC, "🎂 Аналогия: загадай желание на торте",
                    body = "Представь, что **Ojalá = задувание свечей на торте**. Загадываешь желание.\n\n• **Свечи горят сейчас**, и желание ещё может сбыться → **Presente Subj.** (ojalá venga)\n• **Свечи уже задули**, и желание сейчас уже не сбыточно → **Imp. Subj.** (ojalá viniera)\n• **Свечи задули вчера**, и желание было о прошлом → **Pluscuamp. Subj.** (ojalá hubiera venido)\n\nГлавная фишка: **Ojalá ВСЕГДА + Subjuntivo**, никогда не Indicativo! Это табу."),
                TheorySection(TheorySectionType.EXAMPLES, "3 уровня невозможности",
