                    body = "**«Como si»** = «**как будто, словно**». Используется для **сравнения с воображаемой ситуацией**.\n\n**Правило одно и без исключений**: после **como si — ВСЕГДА Imperfecto Subjuntivo** (или Pluscuamperfecto Subj. для прошлого).\n\n• Habla **como si fuera** profesor. (Говорит, **как будто** он профессор — но не профессор.)\n• Me mira **como si no me conociera**. (Смотрит, словно меня не знает.)\n• Actúa **como si tuviera** dinero. (Ведёт себя, **как будто** имеет деньги.)\n\nЭто аналог английского «**as if** I were rich» — тоже past subjunctive."),
                TheorySection(TheorySectionType.MNEMONIC, "🎭 Аналогия: театральная маска",
