            emoji = "🎨", cefr = "B2", readMinutes = 5,
            sections = listOf(
                TheorySection(TheorySectionType.RULE, "Что такое метафорический язык",
                    body = "**Метафорический язык** = когда буквальный смысл слов **уступает образу**. Это особенно сильно в испанском, где **повседневная речь полна метафор**.\n\nПримеры:\n• **Cuesta un ojo de la cara.** (Стоит глаз с лица — очень дорого.)\n• **Tener mala leche.** (Иметь плохое молоко — быть в плохом настроении.)\n• **Estar más solo que la una.** (Быть более одиноким, чем час дня — очень одинок.)\n• **No tener pelos en la lengua.** (Не иметь волос на языке — говорить прямо.)\n\n**Почему так?** Метафоры **рисуют картинку в голове** собеседника, и это **в 10 раз сильнее**, чем простое слово."),
