                TheorySection(TheorySectionType.MNEMONIC, "🎬 Аналогия: метафоры — это короткие фильмы",
                    body = "Каждая метафора = **30-секундный фильм в голове**.\n\n«**Cuesta un ojo de la cara**» = ты буквально видишь, как **отдаёшь глаз** на кассе. **Боль** = понимаешь, что дорого.\n\n«**Estar como una cabra**» = представляешь **прыгающую козу**, которая бегает туда-сюда. **Эксцентрично** = с приветом.\n\n«**Ponerse las pilas**» = представь **робота**, который вставил батарейки и заработал. **Бодрость** = взялся за дело.\n\n**Метод запоминания «фильм + ассоциация»**:\n1. Прочти метафору.\n2. **Закрой глаза** и представь сцену.\n3. Сразу свяжи с реальным смыслом.\n4. Повтори 3 раза — и она в долговременной памяти.\n\nЭто работает потому, что мозг **запоминает образы в 10 раз лучше** чем абстрактные слова."),
