                    body = "**1. В формальном тексте — НЕТ метафор**:\nВ informe escrito или деловом письме нельзя «cuesta un ojo de la cara». Скажи: «Resulta extremadamente costoso.»\n\n**2. С незнакомцами — осторожно**: метафоры **близкие**. Сказать «tienes mala leche» начальнику — **грубо**.\n\n**3. С неносителями — переводи**: иностранец может **не понять** метафору буквально. Если видишь, что не понял — объясни смысл.\n\n**4. Не смешивай регионы**: \n• Испания: **mola** (круто), **flipar** (офигеть), **estar al loro** (быть в курсе).\n• Мексика: **chido**, **alivianar**, **ponerse las pilas** (одинаково).\n• Аргентина: **bárbaro**, **copado**, **estar al pie del cañón**.\n\nЕсли смешать — звучит **искусственно**, как турист, скачавший разговорник.\n\n**5. Уровень = частота**: B2 = знаешь и используешь **самые частые** (20-30 штук). C1 = расширяешь до 100. C2 = понимаешь все, включая литературные."),
